const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const world=document.querySelector('.motion-world'),section=document.querySelector('#performance-world'),pause=document.querySelector('.world-motion-toggle');
const travelers=[...world.querySelectorAll('.world-traveler')].map(el=>{const path=world.querySelector('#'+el.dataset.route);return {el,path,length:path.getTotalLength(),speed:Number(el.dataset.speed),offset:Number(el.dataset.offset)}});
let worldVisible=false,gearVisible=false,fleetVisible=false,paused=false,frame=0,last=0,elapsed=0,gearRender=null,gearLoading=false,gearFailed=false;let pointer={x:0,y:0};
const gear=document.querySelector('.gear-live'),canvas=document.querySelector('#live-gear-canvas'),fleet=document.querySelector('.fleet-ribbon');
function renderWorld(){for(const traveler of travelers){const distance=(traveler.offset*traveler.length+elapsed*traveler.speed)%traveler.length,p=traveler.path.getPointAtLength(distance),q=traveler.path.getPointAtLength(Math.min(traveler.length,distance+.8));const angle=Math.atan2(q.y-p.y,q.x-p.x)*180/Math.PI;traveler.el.setAttribute('transform',`translate(${p.x} ${p.y}) rotate(${angle})`);}}
function running(){return !document.hidden&&!reduced.matches&&!paused&&(worldVisible||fleetVisible||gearVisible&&gearRender);}
function tick(time){frame=0;if(!running())return;const dt=last?Math.min(50,time-last):16;last=time;elapsed+=dt/1000;
 if(worldVisible)renderWorld();
 if(fleetVisible){fleet.style.setProperty('--fleet-car-x',`${(elapsed*42)%(fleet.clientWidth+200)-160}px`);fleet.style.setProperty('--fleet-truck-x',`${(elapsed*27+fleet.clientWidth*.6)%(fleet.clientWidth+260)-220}px`);}
 if(gearVisible&&gearRender){const r=gear.getBoundingClientRect(),progress=Math.max(.5,Math.min(.95,1-r.top/innerHeight));gearRender(time,progress,pointer,false);}
 frame=requestAnimationFrame(tick);
}
function sync(){last=0;const active=running();world.classList.toggle('world-running',active&&worldVisible);fleet.classList.toggle('fleet-running',active&&fleetVisible);if(active&&!frame)frame=requestAnimationFrame(tick);else if(!active&&frame){cancelAnimationFrame(frame);frame=0;}pause.textContent=paused?'Play animation ▷':'Pause animation Ⅱ';pause.setAttribute('aria-pressed',String(paused));}
pause.addEventListener('click',()=>{paused=!paused;sync()});
new IntersectionObserver(entries=>{worldVisible=entries[0].isIntersecting;sync()},{threshold:.12}).observe(world);
new IntersectionObserver(entries=>{fleetVisible=entries[0].isIntersecting;sync()},{threshold:.05}).observe(fleet);
async function loadGear(){if(gearLoading||gearRender||gearFailed)return;gearLoading=true;try{const {mountGearScene}=await import('./gear-scene.js');gearRender=await mountGearScene(canvas,reduced.matches);gearRender(performance.now(),.8,{x:0,y:0},true);gear.classList.add('gear-ready');sync();}catch{gearFailed=true;canvas.hidden=true;}finally{gearLoading=false;}}
new IntersectionObserver(entries=>{gearVisible=entries[0].isIntersecting;if(gearVisible)loadGear();sync()},{threshold:.1,rootMargin:'60px'}).observe(gear);
gear.addEventListener('pointermove',e=>{if(reduced.matches)return;const r=gear.getBoundingClientRect();pointer={x:(e.clientX-r.left)/r.width-.5,y:(e.clientY-r.top)/r.height-.5};});gear.addEventListener('pointerleave',()=>pointer={x:0,y:0});
document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',()=>{renderWorld();if(gearRender&&gearVisible)gearRender(performance.now(),.8,{x:0,y:0},true);sync()});renderWorld();
const data=[{key:'automotive',name:'STÄRK',type:'Automotive lubricants',image:'stark-render.webp',label:'Automotive',title:'Every journey starts within.',description:'Engine oils, transmission fluids, coolants and car care. Explore formulations for the systems that keep vehicles moving.',button:'Explore automotive'},
{key:'diesel',name:'VIRÖ-TEC',type:'Heavy-duty lubricants',image:'viro-transparent.webp',label:'Heavy duty',title:'Built for the long haul.',description:'Diesel engine oil formulations for trucks, fleet vehicles and demanding heavy-duty applications.',button:'Explore diesel oils'},
{key:'industrial',name:'HYDKÖN',type:'Industrial lubricants',image:'hydkon-transparent.webp',label:'Industrial',title:'Precision behind production.',description:'Hydraulic, gear, compressor and specialist oils for machinery and industrial operating requirements.',button:'Explore industrial oils'},
{key:'marine',name:'MARINEÖL',type:'Marine lubricants',image:'range-marine.webp',label:'Marine',title:'Performance beyond the shoreline.',description:'Cylinder, trunk piston and outboard formulations for different marine applications.',button:'Explore marine oils'}];
const tabs=[...world.querySelectorAll('[data-world-tab]')],focus=document.querySelector('#world-focus');let selected=0;
function select(index,keyboard=false){selected=index;const item=data[index];world.dataset.world=item.key;tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1});focus.setAttribute('aria-labelledby',tabs[index].id);document.querySelector('#world-product-name').textContent=item.name;document.querySelector('#world-product-type').textContent=item.type;const image=world.querySelector('.world-product img');image.src='assets/'+item.image;image.alt=item.name+' lubricant product';focus.querySelector('.eyebrow').textContent=item.label;focus.querySelector('h3').textContent=item.title;focus.querySelector('p').textContent=item.description;document.querySelector('#world-explore').innerHTML=item.button+' <span aria-hidden="true">↗</span>';if(!reduced.matches){image.animate([{opacity:.6,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'cubic-bezier(.22,1,.36,1)'});}if(keyboard)tabs[index].focus();}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>select(i));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%4;if(e.key==='ArrowLeft')next=(i+3)%4;if(e.key==='Home')next=0;if(e.key==='End')next=3;if(next!==undefined){e.preventDefault();select(next,true)}})});
document.querySelector('#world-explore').addEventListener('click',()=>window.openCatalog(data[selected].key));
